package pulse

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"time"
)

const base = "https://api.thepulseapi.com/api/v1"

type Signal struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}

type Client struct {
	apiKey string
	orgID  string
	http   *http.Client
}

func New(apiKey, orgID string) *Client {
	return &Client{
		apiKey: apiKey,
		orgID:  orgID,
		// http.DefaultClient has no timeout at all, which is a goroutine leak waiting
		// for a slow upstream. Always supply one.
		http: &http.Client{Timeout: 5 * time.Second},
	}
}

func (c *Client) post(ctx context.Context, path string, body map[string]any, out any) error {
	// organizationId is read from the body rather than from the key, and is required
	// on nearly every endpoint.
	body["organizationId"] = c.orgID

	payload, err := json.Marshal(body)
	if err != nil {
		return err
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, base+path, bytes.NewReader(payload))
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("x-api-key", c.apiKey)

	res, err := c.http.Do(req)
	if err != nil {
		return err
	}
	defer res.Body.Close()

	if res.StatusCode >= 300 {
		return fmt.Errorf("pulse %s: %s", path, res.Status)
	}
	return json.NewDecoder(res.Body).Decode(out)
}

func (c *Client) Track(ctx context.Context, sessionID string, signals []Signal) (map[string]any, error) {
	var out map[string]any
	err := c.post(ctx, "/track", map[string]any{"sessionId": sessionID, "signals": signals}, &out)
	return out, err
}

func (c *Client) RankedCatalog(ctx context.Context, sessionID string, limit int) (map[string]any, error) {
	var out map[string]any
	err := c.post(ctx, "/catalog/ranked", map[string]any{"sessionId": sessionID, "limit": limit}, &out)
	return out, err
}

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.Map;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;

public final class PulseClient {
    private static final String BASE = "https://api.thepulseapi.com/api/v1";

    private final HttpClient http = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(5))
            .build();
    private final ObjectMapper json = new ObjectMapper();
    private final String apiKey;
    private final String organizationId;

    public PulseClient(String apiKey, String organizationId) {
        this.apiKey = apiKey;
        this.organizationId = organizationId;
    }

    public JsonNode track(String sessionId, Object signals) throws Exception {
        return post("/track", Map.of(
                "sessionId", sessionId,
                "organizationId", organizationId,
                "signals", signals));
    }

    public JsonNode rankedCatalog(String sessionId, int limit) throws Exception {
        return post("/catalog/ranked", Map.of(
                "sessionId", sessionId,
                "organizationId", organizationId,
                "limit", limit));
    }

    private JsonNode post(String path, Map<String, Object> body) throws Exception {
        HttpRequest request = HttpRequest.newBuilder(URI.create(BASE + path))
                .header("Content-Type", "application/json")
                .header("x-api-key", apiKey)
                // connectTimeout above only covers establishing the connection. This is the
                // one that bounds a server which accepted the socket and then went quiet.
                .timeout(Duration.ofSeconds(5))
                .POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)))
                .build();

        HttpResponse<String> response = http.send(request, HttpResponse.BodyHandlers.ofString());
        if (response.statusCode() >= 300) {
            throw new IllegalStateException("PULSE " + path + ": " + response.statusCode());
        }
        return json.readTree(response.body());
    }
}

import { PulseClient } from '@thepulseapi/sdk';

// One client per process. It holds no per-shopper state: the session id is passed per call.
export const pulse = new PulseClient();

pulse.init({
  apiKey: process.env.PULSE_API_KEY!,
  organizationId: process.env.PULSE_ORG_ID!,
  autoTrack: false, // there is no browser here to capture a device or a referrer from
});

const BASE = 'https://api.thepulseapi.com/api/v1';

async function post<T>(path: string, body: Record<string, unknown>): Promise<T> {
  const response = await fetch(`${BASE}${path}`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-api-key': process.env.PULSE_API_KEY!,
    },
    body: JSON.stringify({ organizationId: process.env.PULSE_ORG_ID, ...body }),
    // fetch has no default timeout, and a hung ranking call should not hold a request.
    signal: AbortSignal.timeout(5000),
  });

  if (!response.ok) throw new Error(`PULSE ${path}: ${response.status}`);
  return response.json() as Promise<T>;
}

export const track = (sessionId: string, signals: unknown[]) =>
  post('/track', { sessionId, signals });

export const rankedCatalog = (sessionId: string, limit = 24) =>
  post('/catalog/ranked', { sessionId, limit });

from django.shortcuts import render
from .pulse import pulse


def category(request, slug):
    # The browser owns the session. Read it rather than minting a second one for the
    # same shopper: two session ids means the inference starts from nothing twice.
    session_id = request.COOKIES.get("pulse_session")
    products = []

    if session_id:
        try:
            products = pulse.ranked_catalog(session_id, limit=24, categorySlug=slug)["items"]
        except Exception:
            # Ranking is an enhancement. A page that fails to render because personalisation
            # was slow is worse than a page in catalogue order.
            products = []

    return render(request, "category.html", {"products": products or default_order(slug)})

